            let unknown: Vec<&str> = unknown.iter().map(String::as_str).collect();
            return Err(crate::kernel::Refusal::UnknownArgument(
                crate::kernel::refusal_wording::UnknownArgumentUnknownArgsArgs {
                    command: "ArgumentSeed",
                    unknown: &unknown,
                    declared: &[
                        "keyword",
                        "context",
                        "at",
                        "named",
                        "kind",
                        "required",
                        "fills",
                        "selects",
                        "pair_key_fills",
                        "pair_value_fills",
                        "pairs_shape",
                        "status",
                        "variadic",
                        "coerce",
                        "blank_message",
                    ],
                }
                .render_args(),
            ));
