pub static QUERY_PROJECTED_FIELDS: &[crate::kernel::ProjectedFieldSpec] = &[];

impl Query {
    pub fn extract_id(v: &crate::kernel::Json) -> Result<String, crate::kernel::Refusal> {
        let by_identity = (|| -> Option<String> {
            let c0 = v.dig("owner_id")?.to_id_component().ok()?;
            let c1 = v.dig("name.value")?.to_id_component().ok()?;
            Some([c0, c1].join(":"))
        })();
        let by_id_key = v.get("id").and_then(|j| j.to_id_component().ok());
        let by_reference_key = v.get("query").and_then(|j| j.to_id_component().ok());

        by_identity
            .or(by_id_key)
            .or(by_reference_key)
            .ok_or_else(|| {
                crate::kernel::Refusal::TypeMismatch(
                    "Query: no identity found (tried owner_id, name.value, id, query)".to_string(),
                )
            })
    }
}

fn query_invariants() -> crate::kernel::InvariantSet {
    crate::kernel::InvariantSet {
        aggregate: vec![],
        entities: vec![],
    }
}

